// Normaliza o evento da Evolution API. Nenhuma IA participa desta etapa.
// Decide tambem a rota de entrada: mensagem do cliente, mensagem do negocio ou descarte.
const LIMITE_TEXTO = 2000;

// Origens dos servicos. Nao sao segredo (o token vai em credencial do n8n),
// mas mudam por ambiente: este e o UNICO lugar do fluxo para troca-las.
// Nao leia isto do ambiente: N8N_BLOCK_ENV_ACCESS_IN_NODE=true nesta VPS, entao
// a expressao lanca "access to env vars denied" no worker e o no morre calado.
const API_BASE = 'https://agenda-magnetica-painel.vercel.app';
const EVOLUTION_BASE = 'https://evo.fixwear.com.br';

const raiz = $input.first().json;
const body = raiz.body || raiz;
const data = body.data || {};
const chave = data.key || {};
const mensagem = data.message || {};

const remoteJid = String(chave.remoteJid || '');
const instance = String(body.instance || '');
const msgId = String(chave.id || '');
const fromMe = chave.fromMe === true;
const evento = String(body.event || '');

const texto = mensagem.conversation
  || (mensagem.extendedTextMessage && mensagem.extendedTextMessage.text)
  || (mensagem.imageMessage && mensagem.imageMessage.caption)
  || '';

let tipo = 'outro';
let mimetype = '';
if (mensagem.audioMessage) {
  tipo = 'audio';
  mimetype = mensagem.audioMessage.mimetype || 'audio/ogg';
} else if (mensagem.imageMessage) {
  tipo = 'imagem';
  mimetype = mensagem.imageMessage.mimetype || 'image/jpeg';
} else if (String(texto).trim()) {
  tipo = 'texto';
}

// Conversa individual apenas: grupos (@g.us) e status@broadcast ficam de fora.
const individual = remoteJid.endsWith('@s.whatsapp.net');

let rota = 'ignorar';
let motivo = '';
if (evento !== 'messages.upsert') motivo = 'evento_nao_suportado';
else if (!individual) motivo = 'conversa_nao_individual';
else if (!msgId || !instance) motivo = 'evento_incompleto';
else if (fromMe) { rota = 'humano'; motivo = 'mensagem_enviada_pelo_negocio'; }
else if (tipo === 'outro') motivo = 'tipo_de_mensagem_nao_suportado';
else rota = 'cliente';

return [{
  json: {
    rota_entrada: rota,
    motivo,
    instance,
    remote_jid: remoteJid,
    telefone: remoteJid.replace('@s.whatsapp.net', ''),
    msg_id: msgId,
    from_me: fromMe,
    evento,
    tipo,
    conteudo: String(texto).slice(0, LIMITE_TEXTO),
    base64: String(mensagem.base64 || data.base64 || ''),
    mimetype,
    push_name: String(data.pushName || '').slice(0, 60),
    timestamp: Number(data.messageTimestamp || 0),
    api_base: API_BASE.replace(/\/$/, ''),
    evolution_base: EVOLUTION_BASE.replace(/\/$/, ''),
  },
}];

// Agrupa mensagens proximas do mesmo contato. So a execucao da ultima mensagem
// do buffer segue adiante; as anteriores encerram sem resposta.
const entrada = $('normalizar entrada').first().json;
const bruto = $input.first().json.buffer;

let lista = [];
if (Array.isArray(bruto)) lista = bruto;
else if (typeof bruto === 'string' && bruto) lista = [bruto];

const itens = lista
  .map((x) => {
    if (x && typeof x === 'object') return x;
    try { return JSON.parse(x); } catch (e) { return null; }
  })
  .filter((x) => x && x.msg_id);

// Buffer perdido (expiracao/reinicio do Redis): usa somente a mensagem atual.
const efetivos = itens.length ? itens : [entrada];
const ultimo = efetivos[efetivos.length - 1];

if (ultimo.msg_id !== entrada.msg_id) {
  return [{ json: { processar: false, motivo: 'mensagem_mais_recente_assume' } }];
}

const textos = efetivos.map((i) => String(i.conteudo || '').trim()).filter(Boolean);
const midia = [...efetivos].reverse().find((i) => i.tipo === 'audio' || i.tipo === 'imagem') || null;

return [{
  json: {
    processar: true,
    motivo: 'ultima_mensagem_do_buffer',
    quantidade: efetivos.length,
    tipo: midia ? midia.tipo : 'texto',
    conteudo: textos.join('\n'),
    base64: midia ? String(midia.base64 || '') : '',
    mimetype: midia ? String(midia.mimetype || '') : '',
  },
}];

// Fim do atendimento quando /api/ai/contexto respondeu `ok: false`.
// Nem todo `ok: false` e igual: RECUSA_DE_NEGOCIO e a empresa dizendo nao
// (atendimento desligado, instancia de outro produto, cadastro incompleto) e
// encerrar calado e o comportamento certo. Qualquer outro codigo — ou resposta
// sem envelope — e a integracao quebrada, e ai o silencio e o pior resultado
// possivel: o cliente fica sem resposta e ninguem fica sabendo, porque
// `saveDataSuccessExecution: none` nao guarda execucao que terminou bem.
const RECUSA_DE_NEGOCIO = [
  'AUTOMACAO_DESATIVADA',      // o dono desligou o atendimento no painel
  'INSTANCIA_DESCONHECIDA',    // a instancia nao pertence a este produto
  'EMPRESA_NAO_CONFIGURADA',   // onboarding incompleto
];

const erro = ($input.first().json || {}).error || {};
const codigo = String(erro.code || '');

if (!RECUSA_DE_NEGOCIO.includes(codigo)) {
  // Mensagem so com o codigo: `message` da API e seguro, mas nao ha motivo
  // para copiar corpo de resposta para dentro do log de execucao.
  throw new Error(
    'contexto indisponivel por falha, nao por regra: ' +
    (codigo || 'resposta sem envelope') +
    '. Confira AUTOMATION_API_TOKEN nas variaveis do projeto na Vercel e a ' +
    'credencial "Agenda Magnetica - token da automacao" no n8n.'
  );
}

return [{ json: { encerrado_por: codigo } }];

// Monta o contexto minimo enviado a IA. Tudo vem de uma unica chamada a
// /api/ai/contexto: a empresa e derivada da instancia no servidor, o cliente e
// localizado ou criado dentro dela e o catalogo e o dela. Nenhum id de empresa
// ou de cliente circula por aqui: as rotas da API nao aceitam esses parametros.
const HISTORICO_MAX = 6;
const FUSO_PADRAO = 'America/Sao_Paulo';
const OFFSET_MIN = -180; // America/Sao_Paulo nao usa horario de verao desde 2019.

const entrada = $('normalizar entrada').first().json;
const conteudoItem = $('conteudo do cliente').first().json;
const envelope = $('contexto da empresa').first().json || {};
const chaves = $input.first().json;

// Sem envelope valido nao existe contexto. O fluxo nao completa empresa nem
// cliente por conta propria: quem nao tem contexto vai para uma pessoa.
const dados = (envelope.ok === true && envelope.data) ? envelope.data : {};
const empresaApi = dados.empresa || {};
const clienteApi = dados.cliente || {};

function texto(v) { return v === null || v === undefined ? '' : String(v); }
function numero(v) { const n = Number(v); return Number.isFinite(n) ? n : null; }
function lista(v) { return Array.isArray(v) ? v : []; }

// Nome de exibicao: push name do WhatsApp costuma trazer nome de empresa, apelido
// ou emoji. So usamos quando parece um primeiro nome de pessoa.
const MARCAS_DE_NEGOCIO = [
  'ltda', 'mei', 'me ', 'studio', 'estúdio', 'salão', 'salao', 'clínica', 'clinica',
  'consultório', 'consultorio', 'espaço', 'espaco', 'barbearia', 'atelier', 'ateliê',
  'center', 'centro', 'serviços', 'servicos', 'com.br', 'www', 'oficial', 'delivery',
];

function primeiroNomeConfiavel(nome) {
  const limpo = texto(nome).trim();
  if (!limpo) return '';
  const comparavel = limpo.toLowerCase();
  if (MARCAS_DE_NEGOCIO.some((m) => comparavel.includes(m))) return '';
  if (/\d/.test(limpo)) return '';
  const primeiro = limpo.split(/\s+/)[0];
  if (primeiro.length < 2 || primeiro.length > 20) return '';
  if (!/^[A-Za-zÀ-ÿ'’-]+$/.test(primeiro)) return '';
  return primeiro.charAt(0).toUpperCase() + primeiro.slice(1).toLowerCase();
}

const agora = new Date();
const agoraLocal = new Date(agora.getTime() + OFFSET_MIN * 60000);

const servicos = lista(dados.procedimentos)
  .map((p) => ({
    id: numero(p.id),
    nome: texto(p.nome),
    valor: numero(p.valor),
    duracao_minutos: numero(p.duracao_minutos) || 60,
    // agendavel: false = nenhum profissional ativo executa o servico. Ele tem
    // preco para responder uma duvida, mas nunca teria horario livre.
    agendavel: p.agendavel !== false,
  }))
  .filter((p) => p.id && p.nome);

const profissionais = lista(dados.profissionais)
  .map((p) => ({ id: numero(p.id), nome: texto(p.nome), area: texto(p.area) }))
  .filter((p) => p.id && p.nome);

const horarios = lista(empresaApi.horarios)
  .map((h) => ({
    dia_semana: numero(h.dia_semana),
    hora_inicio: texto(h.hora_inicio),
    hora_fim: texto(h.hora_fim),
  }))
  .filter((h) => h.dia_semana !== null);

let pendente = null;
try {
  const cru = chaves.pendente;
  const obj = typeof cru === 'string' ? JSON.parse(cru) : cru;
  if (obj && obj.tipo) pendente = obj;
} catch (e) { pendente = null; }

let estado = { historico: [], slots_oferecidos: [], consultas_candidatas: [], reagendar_consulta_id: null };
try {
  const cru = chaves.estado;
  const obj = typeof cru === 'string' ? JSON.parse(cru) : cru;
  if (obj && typeof obj === 'object') estado = Object.assign(estado, obj);
} catch (e) { /* estado ausente e um caso normal */ }

const nomeCliente = texto(clienteApi.nome) || entrada.push_name;
// O telefone normalizado pela API e a identidade do cliente nas proximas
// chamadas. Sem ele nao ha operacao possivel, e o fluxo transfere.
const telefoneCliente = texto(clienteApi.telefone);
const temContexto = Boolean(dados.empresa && telefoneCliente);

return [{
  json: {
    tem_contexto: temContexto,
    erro_contexto: temContexto ? null : texto((envelope.error || {}).code) || 'sem_envelope',
    agora_iso: agora.toISOString(),
    agora_local: agoraLocal.toISOString().replace('Z', '-03:00'),
    fuso: texto(empresaApi.fuso) || FUSO_PADRAO,
    empresa: {
      nome: texto(empresaApi.nome) || 'nosso atendimento',
      telefone: texto(empresaApi.telefone),
      email: texto(empresaApi.email),
      endereco: texto(empresaApi.endereco),
      assistente_nome: texto(empresaApi.assistente_nome) || 'assistente virtual',
      assistente_tom: texto(empresaApi.assistente_tom) || 'cordial, direto e simples',
      exige_profissional: empresaApi.exige_profissional === true,
    },
    servicos,
    profissionais,
    horarios,
    cliente: {
      nome: nomeCliente,
      primeiro_nome: primeiroNomeConfiavel(nomeCliente),
      telefone: telefoneCliente,
      novo: clienteApi.novo === true,
      tem_cadastro_confirmado: Boolean(texto(clienteApi.nome)),
    },
    pendente,
    estado: {
      historico: Array.isArray(estado.historico) ? estado.historico.slice(-HISTORICO_MAX) : [],
      slots_oferecidos: Array.isArray(estado.slots_oferecidos) ? estado.slots_oferecidos : [],
      consultas_candidatas: Array.isArray(estado.consultas_candidatas) ? estado.consultas_candidatas : [],
      reagendar_consulta_id: numero(estado.reagendar_consulta_id),
    },
    conteudo: texto(conteudoItem.conteudo),
    tipo_entrada: texto(conteudoItem.tipo) || 'texto',
    entrada_incerta: conteudoItem.entrada_incerta === true,
    msg_id: entrada.msg_id,
    instance: entrada.instance,
    remote_jid: entrada.remote_jid,
  },
}];

// Valida a saida da IA fora da IA. Nada aqui confia no modelo: enum fechado,
// tipos coeridos, ids internos descartados e next_action recalculado.
const INTENCOES = [
  'saudacao', 'faq', 'consultar_disponibilidade', 'preparar_agendamento',
  'confirmar_acao', 'recusar_acao', 'consultar_agendamento', 'preparar_reagendamento',
  'preparar_cancelamento', 'atualizar_cadastro', 'falar_com_humano', 'fora_do_escopo',
];
const ACOES = [
  'answer', 'ask_clarification', 'check_availability', 'confirm_pending',
  'discard_pending', 'list_appointments', 'update_customer', 'handoff',
];
// next_action e sempre derivada da intencao pelo sistema; o campo da IA e ignorado.
const ACAO_POR_INTENCAO = {
  saudacao: 'answer',
  faq: 'answer',
  fora_do_escopo: 'answer',
  consultar_disponibilidade: 'check_availability',
  preparar_agendamento: 'check_availability',
  confirmar_acao: 'confirm_pending',
  recusar_acao: 'discard_pending',
  consultar_agendamento: 'list_appointments',
  preparar_reagendamento: 'list_appointments',
  preparar_cancelamento: 'list_appointments',
  atualizar_cadastro: 'update_customer',
  falar_com_humano: 'handoff',
};
const PERIODOS = ['manha', 'tarde', 'noite'];
const CAMPOS_CADASTRO = ['nome', 'email', 'data_nascimento', 'interesses'];

const bruto = $input.first().json;
let saida = bruto.output !== undefined ? bruto.output : bruto;
if (typeof saida === 'string') {
  const limpo = saida.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try { saida = JSON.parse(limpo); } catch (e) { saida = null; }
}

if (!saida || typeof saida !== 'object') {
  return [{ json: { valida: false, motivo: 'saida_nao_estruturada', interp: null } }];
}

function texto(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  return s && s.toLowerCase() !== 'null' ? s.slice(0, 200) : null;
}

const intencao = INTENCOES.includes(saida.intent) ? saida.intent : null;
if (!intencao) {
  return [{ json: { valida: false, motivo: 'intencao_fora_do_enum', interp: null } }];
}

let confianca = Number(saida.confidence);
if (!Number.isFinite(confianca)) confianca = 0;
confianca = Math.min(1, Math.max(0, confianca));

const ent = (saida.entities && typeof saida.entities === 'object') ? saida.entities : {};
const atualizacoesBrutas = (ent.customer_updates && typeof ent.customer_updates === 'object') ? ent.customer_updates : {};
const atualizacoes = {};
for (const campo of CAMPOS_CADASTRO) {
  const valor = texto(atualizacoesBrutas[campo]);
  if (valor) atualizacoes[campo] = valor;
}

const periodo = PERIODOS.includes(ent.period) ? ent.period : null;
const acaoIA = ACOES.includes(saida.next_action) ? saida.next_action : null;

const interp = {
  version: '1.0',
  intent: intencao,
  confidence: confianca,
  entities: {
    service_query: texto(ent.service_query),
    professional_query: texto(ent.professional_query),
    date_text: texto(ent.date_text),
    time_text: texto(ent.time_text),
    period: periodo,
    appointment_hint: texto(ent.appointment_hint),
    customer_updates: atualizacoes,
  },
  next_action: ACAO_POR_INTENCAO[intencao],
  next_action_ia: acaoIA,
  requires_confirmation: saida.requires_confirmation === true,
  requires_human: saida.requires_human === true,
  handoff_reason: texto(saida.handoff_reason),
  reply: String(saida.reply === null || saida.reply === undefined ? '' : saida.reply).slice(0, 700),
};

return [{ json: { valida: true, motivo: 'ok', interp } }];

// Regras deterministicas do atendimento. A IA nao escolhe id, data, rota,
// filtro, ferramenta nem resultado: tudo e resolvido aqui. As chamadas de
// agenda saem prontas daqui (caminho e corpo), para que a repeticao de uma
// escrita use exatamente o mesmo pedido, com a mesma chave de idempotencia.
const LIMIAR_PADRAO = 0.75;      // ajuste unico para pedir esclarecimento
const LIMIAR_DESTRUTIVO = 0.85;  // cancelar / reagendar / confirmar
const LIMIAR_HUMANO = 0.45;      // abaixo disso, pessoa assume
const JANELA_PADRAO_DIAS = 14;
const PASSO_MINUTOS = 30;
const LIMITE_SLOTS = 12;         // horarios pedidos por busca; ofertamos 2
const OFFSET_MIN = -180; // America/Sao_Paulo, sem horario de verao desde 2019

const PERIODOS = { manha: [8, 12], tarde: [12, 18], noite: [18, 21] };
const DIA_INICIO = 7;
const DIA_FIM = 21;

const TERMOS_SENSIVEIS = [
  'dor ', 'dores', 'doi', 'sangr', 'infec', 'febre', 'pus', 'inflam', 'alergi', 'remedio',
  'pomada', 'antibiotic', 'diagnostic', 'gravid', 'gestante', 'diabet',
  'anticoagul', 'cancer', 'tumor', 'ferida', 'machuc', 'lesao', 'medicament',
];

const ctx = $('montar contexto').first().json;
const validacao = $input.first().json;

function normalizar(s) {
  return String(s === null || s === undefined ? '' : s)
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s/:-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function pad(n) { return String(n).padStart(2, '0'); }
function partesLocais(iso) {
  const d = new Date(new Date(iso).getTime() + OFFSET_MIN * 60000);
  return {
    ano: d.getUTCFullYear(), mes: d.getUTCMonth() + 1, dia: d.getUTCDate(),
    hora: d.getUTCHours(), min: d.getUTCMinutes(), dow: d.getUTCDay(),
  };
}
function isoLocal(p, hora, min) {
  return `${p.ano}-${pad(p.mes)}-${pad(p.dia)}T${pad(hora)}:${pad(min)}:00-03:00`;
}
function somarDias(p, n) {
  const d = new Date(Date.UTC(p.ano, p.mes - 1, p.dia));
  d.setUTCDate(d.getUTCDate() + n);
  return { ano: d.getUTCFullYear(), mes: d.getUTCMonth() + 1, dia: d.getUTCDate(), dow: d.getUTCDay() };
}

const agora = partesLocais(ctx.agora_iso);
const conteudoNorm = normalizar(ctx.conteudo);

// ---------- datas ----------
const DIAS_SEMANA = {
  domingo: 0, segunda: 1, terca: 2, quarta: 3, quinta: 4, sexta: 5, sabado: 6,
};
const MESES = {
  janeiro: 1, fevereiro: 2, marco: 3, abril: 4, maio: 5, junho: 6, julho: 7,
  agosto: 8, setembro: 9, outubro: 10, novembro: 11, dezembro: 12,
};

function resolverData(textoData) {
  const t = normalizar(textoData);
  if (!t) return { tipo: null };
  if (/\bhoje\b|\bhj\b|\bagora\b/.test(t)) return { tipo: 'dia', p: agora, ambiguo: false };
  if (/depois de amanha/.test(t)) return { tipo: 'dia', p: somarDias(agora, 2), ambiguo: false };
  if (/\bamanha\b/.test(t)) return { tipo: 'dia', p: somarDias(agora, 1), ambiguo: false };

  const dm = t.match(/\b(\d{1,2})[/-](\d{1,2})(?:[/-](\d{2,4}))?\b/);
  if (dm) {
    const dia = Number(dm[1]); const mes = Number(dm[2]);
    let ano = dm[3] ? Number(dm[3]) : agora.ano;
    if (ano < 100) ano += 2000;
    if (dia >= 1 && dia <= 31 && mes >= 1 && mes <= 12) {
      let p = { ano, mes, dia };
      // Data recente no passado continua no passado: quem falou "19/08" ontem
      // precisa ouvir que ja passou, e nao ser jogado para o ano que vem.
      if (!dm[3]) {
        const candidato = Date.UTC(ano, mes - 1, dia);
        const hoje = Date.UTC(agora.ano, agora.mes - 1, agora.dia);
        if (candidato < hoje - 60 * 86400000) p = { ano: ano + 1, mes, dia };
      }
      return { tipo: 'dia', p, ambiguo: false };
    }
  }

  const dmExtenso = t.match(/\bdia (\d{1,2})(?: de ([a-z]+))?/);
  if (dmExtenso) {
    const dia = Number(dmExtenso[1]);
    const mes = dmExtenso[2] && MESES[dmExtenso[2]] ? MESES[dmExtenso[2]] : agora.mes;
    if (dia >= 1 && dia <= 31) return { tipo: 'dia', p: { ano: agora.ano, mes, dia }, ambiguo: false };
  }

  if (/semana que vem|proxima semana/.test(t)) {
    return { tipo: 'janela', p: somarDias(agora, 7), dias: 6, ambiguo: false };
  }

  for (const nome of Object.keys(DIAS_SEMANA)) {
    if (new RegExp(`\\b${nome}`).test(t)) {
      const alvo = DIAS_SEMANA[nome];
      let delta = (alvo - agora.dow + 7) % 7;
      const proxima = /que vem|proxim/.test(t);
      if (delta === 0 && proxima) delta = 7;
      const ambiguo = delta === 0 && !proxima && !/\bhoje\b/.test(t);
      return { tipo: 'dia', p: somarDias(agora, delta), ambiguo, nome_dia: nome };
    }
  }
  return { tipo: null };
}

function resolverHora(textos) {
  // Remove datas antes de procurar hora: "14/03" nao pode virar 14h.
  const t = normalizar(textos.join(' ')).replace(/\b\d{1,2}[/-]\d{1,2}(?:[/-]\d{2,4})?\b/g, ' ');
  if (/meio dia/.test(t)) return { hora: 12, min: 0 };
  const m = t.match(/\b(\d{1,2})(?:[:h](\d{2}))?\s*(?:h|hs|horas)?\b/);
  if (!m) return null;
  let hora = Number(m[1]);
  const min = m[2] ? Number(m[2]) : 0;
  if (hora > 23 || min > 59) return null;
  if (/da tarde|a tarde/.test(t) && hora <= 11) hora += 12;
  if (/da noite|a noite/.test(t) && hora <= 11) hora += 12;
  if (!/[:h]/.test(m[0]) && !/hora|\bh\b/.test(t) && hora <= 7) return null;
  return { hora, min };
}

// ---------- catalogo ----------
// Servico com agendavel: false nunca teria horario livre. Ele continua no
// catalogo para responder duvida de preco, mas sai das listas de oferta.
const AGENDAVEIS = ctx.servicos.filter((s) => s.agendavel !== false);
function nomesAgendaveis() { return AGENDAVEIS.map((s) => s.nome); }

function acharServico(consulta) {
  const q = normalizar(consulta);
  const lista = ctx.servicos;
  if (!lista.length) return { status: 'catalogo_vazio' };
  const mencionados = lista.filter((s) => conteudoNorm.includes(normalizar(s.nome)));
  if (mencionados.length > 1) return { status: 'ambiguo', opcoes: mencionados };
  if (!q) return mencionados.length === 1 ? { status: 'ok', servico: mencionados[0] } : { status: 'ausente' };
  const exato = lista.filter((s) => normalizar(s.nome) === q);
  if (exato.length === 1) return { status: 'ok', servico: exato[0] };
  const contem = lista.filter((s) => normalizar(s.nome).includes(q) || q.includes(normalizar(s.nome)));
  if (contem.length === 1) return { status: 'ok', servico: contem[0] };
  if (contem.length > 1) return { status: 'ambiguo', opcoes: contem };
  const tokens = q.split(' ').filter((t) => t.length > 3);
  const porToken = lista.filter((s) => { const n = normalizar(s.nome); return tokens.some((t) => n.includes(t)); });
  if (porToken.length === 1) return { status: 'ok', servico: porToken[0] };
  if (porToken.length > 1) return { status: 'ambiguo', opcoes: porToken };
  return { status: 'nao_encontrado' };
}

function acharProfissional(consulta) {
  const q = normalizar(consulta);
  if (!q) return { status: 'ausente' };
  const achados = ctx.profissionais.filter((p) => {
    const n = normalizar(p.nome);
    return n === q || n.includes(q) || q.includes(n.split(' ')[0]);
  });
  if (achados.length === 1) return { status: 'ok', profissional: achados[0] };
  if (achados.length > 1) return { status: 'ambiguo', opcoes: achados };
  return { status: 'nao_encontrado' };
}

function escolherSlotOferecido(entidades) {
  const slots = ctx.estado.slots_oferecidos || [];
  if (!slots.length) return null;
  if (/\bprimeir|\bopcao 1\b/.test(conteudoNorm) && slots[0]) return slots[0];
  if (/\bsegund|\bopcao 2\b/.test(conteudoNorm) && slots[1]) return slots[1];
  const h = resolverHora([entidades.time_text || '', ctx.conteudo]);
  if (h) {
    const alvo = slots.find((s) => {
      const p = partesLocais(s.inicio);
      return p.hora === h.hora && (h.min === 0 || p.min === h.min);
    });
    if (alvo) return alvo;
  }
  if (slots.length === 1 && /\bsim\b|\bpode\b|\bisso\b|\bserve\b|\bquero\b|\bfechado\b|\bbeleza\b|\bok\b/.test(conteudoNorm)) return slots[0];
  return null;
}

function resposta(tipo, dados) {
  return { tipo, dados: dados || {} };
}

function saida(rota, extra) {
  return [{
    json: Object.assign({
      rota,
      contexto: ctx,
      interp: interp,
      log: {
        msg_id: ctx.msg_id,
        instance: ctx.instance,
        intent: interp ? interp.intent : null,
        confidence: interp ? interp.confidence : null,
        rota,
      },
    }, extra),
  }];
}

// ---------- pedidos prontos para a API ----------
// Caminho e corpo saem daqui uma unica vez: os nos de escrita e a repeticao
// usam o mesmo objeto, entao repetir nunca muda a chave de idempotencia.
function montarEscrita(p) {
  const base = { instance_name: ctx.instance, telefone: ctx.cliente.telefone };
  if (p.tipo === 'cancelar') {
    return {
      caminho: '/api/ai/agendamentos/cancelar',
      corpo: Object.assign({}, base, { id_consulta: p.consulta_id, motivo: 'cliente_solicitou' }),
    };
  }
  if (p.tipo === 'reagendar') {
    // Reagendar e idempotente por estado: a API recusa chave_idempotencia aqui.
    return {
      caminho: '/api/ai/agendamentos/reagendar',
      corpo: Object.assign({}, base, {
        id_consulta: p.consulta_id,
        novo_inicio: p.inicio,
        id_profissional: p.profissional_id || null,
      }),
    };
  }
  return {
    caminho: '/api/ai/agendamentos',
    corpo: Object.assign({}, base, {
      id_procedimento: p.servico_id,
      id_profissional: p.profissional_id,
      inicio: p.inicio,
      chave_idempotencia: String(p.acao_id || '').slice(0, 120),
    }),
  };
}

function montarBusca(pDia, periodo, servicoId, profissionalId) {
  let hIni = DIA_INICIO; let mIni = 0; let hFim = DIA_FIM;
  if (periodo && PERIODOS[periodo]) { hIni = PERIODOS[periodo][0]; hFim = PERIODOS[periodo][1]; }
  const ehHoje = pDia.ano === agora.ano && pDia.mes === agora.mes && pDia.dia === agora.dia;
  if (ehHoje && agora.hora >= hIni) { hIni = agora.hora; mIni = agora.min; }
  return {
    instance_name: ctx.instance,
    id_procedimento: servicoId,
    id_profissional: profissionalId || null,
    inicio: isoLocal(pDia, hIni, mIni),
    fim: isoLocal(pDia, hFim, 0),
    passo_minutos: PASSO_MINUTOS,
    limite: LIMITE_SLOTS,
  };
}

// Janela vazia acontece de verdade: "hoje a tarde" perguntado as 20h. A API
// recusaria com ENTRADA_INVALIDA, e isso viraria transferencia por engano.
function irBuscarHorarios(busca, extra) {
  if (new Date(busca.inicio).getTime() >= new Date(busca.fim).getTime()) {
    return saida('responder', {
      motivo: 'fora_do_expediente',
      resposta: resposta('sem_horarios', { servico: extra.servico, ate: busca.fim }),
    });
  }
  return saida('disponibilidade', Object.assign({ busca }, extra));
}

// ---------- decisao ----------
let interp = validacao.interp;

if (!validacao.valida || !interp) {
  return saida('humano', {
    motivo: validacao.motivo || 'interpretacao_invalida',
    handoff_motivo: 'interpretacao_invalida',
    resposta: resposta('humano', {}),
  });
}

if (!ctx.tem_contexto) {
  return saida('humano', {
    motivo: 'contexto_incompleto',
    handoff_motivo: ctx.erro_contexto || 'contexto_incompleto',
    resposta: resposta('humano', {}),
  });
}

const ent = interp.entities;
const perguntaSensivel = TERMOS_SENSIVEIS.some((t) => conteudoNorm.includes(t))
  && /\?|\bpode\b|\bposso\b|\be normal\b|\bo que\b|\bserve\b|\btomar\b|\bpassar\b/.test(conteudoNorm)
  && ['faq', 'saudacao', 'fora_do_escopo'].includes(interp.intent);

if (interp.requires_human || interp.intent === 'falar_com_humano' || perguntaSensivel || interp.confidence < LIMIAR_HUMANO) {
  return saida('humano', {
    motivo: 'transferencia',
    handoff_motivo: perguntaSensivel ? 'assunto_sensivel'
      : (interp.confidence < LIMIAR_HUMANO ? 'confianca_baixa' : (interp.handoff_reason || 'pedido_do_cliente')),
    resposta: resposta('humano', {}),
  });
}

const destrutiva = ['preparar_cancelamento', 'preparar_reagendamento', 'confirmar_acao'].includes(interp.intent);
const limiar = destrutiva ? LIMIAR_DESTRUTIVO : LIMIAR_PADRAO;
if (interp.confidence < limiar) {
  return saida('responder', {
    motivo: 'confianca_abaixo_do_limiar',
    resposta: resposta('esclarecer', { reply: interp.reply }),
  });
}

// Confirmacao: so executa a acao pendente guardada pelo sistema.
if (interp.next_action === 'confirm_pending') {
  const pendente = ctx.pendente;
  if (pendente && pendente.expira_em && new Date(pendente.expira_em).getTime() < new Date(ctx.agora_iso).getTime()) {
    return saida('responder', { motivo: 'pendente_expirada', resposta: resposta('pendente_expirada', {}) });
  }
  if (pendente && pendente.tipo) {
    // A API revalida o horario com a funcao do banco imediatamente antes de
    // gravar, entao o fluxo nao repete a consulta de disponibilidade aqui.
    return saida('executar_pendente', {
      motivo: 'confirmacao_valida',
      pendente,
      escrita: montarEscrita(pendente),
    });
  }
  const alvo = escolherSlotOferecido(ent);
  if (alvo && alvo.servico_id) {
    return irBuscarHorarios(
      montarBusca(partesLocais(alvo.inicio), null, alvo.servico_id, alvo.profissional_id),
      {
        motivo: 'selecao_de_horario_oferecido',
        servico: { id: alvo.servico_id, nome: alvo.servico_nome, duracao_minutos: alvo.duracao_minutos },
        profissional: alvo.profissional_id ? { id: alvo.profissional_id, nome: alvo.profissional_nome } : null,
        horario_desejado: alvo.inicio,
        reagendar_consulta_id: ctx.estado.reagendar_consulta_id,
      },
    );
  }
  if ((ctx.estado.slots_oferecidos || []).length > 1) {
    return saida('responder', { motivo: 'escolha_ambigua', resposta: resposta('qual_horario', { slots: ctx.estado.slots_oferecidos }) });
  }
  return saida('responder', { motivo: 'sem_pendente', resposta: resposta('sem_pendente', {}) });
}

if (interp.next_action === 'discard_pending') {
  return saida('descartar_pendente', { motivo: 'cliente_recusou', resposta: resposta('pendente_descartada', {}) });
}

if (interp.next_action === 'handoff') {
  return saida('humano', { motivo: 'pedido_do_cliente', handoff_motivo: 'pedido_do_cliente', resposta: resposta('humano', {}) });
}

if (interp.next_action === 'answer') {
  return saida('responder', { motivo: 'resposta_conversacional', resposta: resposta('livre', { reply: interp.reply }) });
}

if (interp.next_action === 'update_customer') {
  const campos = ent.customer_updates || {};
  if (!Object.keys(campos).length) {
    return saida('responder', { motivo: 'cadastro_sem_dado_explicito', resposta: resposta('esclarecer', { reply: interp.reply }) });
  }
  if (campos.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(campos.email)) delete campos.email;
  if (campos.data_nascimento && !/^\d{4}-\d{2}-\d{2}$/.test(campos.data_nascimento)) {
    const br = String(campos.data_nascimento).match(/^(\d{2})[/-](\d{2})[/-](\d{4})$/);
    if (br) campos.data_nascimento = `${br[3]}-${br[2]}-${br[1]}`;
    else delete campos.data_nascimento;
  }
  if (!Object.keys(campos).length) {
    return saida('responder', { motivo: 'cadastro_invalido', resposta: resposta('esclarecer', { reply: interp.reply }) });
  }
  return saida('atualizar_cadastro', { motivo: 'dados_explicitos', atualizacoes: campos });
}

if (interp.next_action === 'list_appointments') {
  const objetivo = interp.intent === 'preparar_cancelamento' ? 'cancelar'
    : (interp.intent === 'preparar_reagendamento' ? 'reagendar' : 'listar');
  return saida('consultas_do_cliente', { motivo: `consultas_para_${objetivo}`, objetivo });
}

// ---------- disponibilidade ----------
const escolhido = escolherSlotOferecido(ent);
const buscaServico = acharServico(ent.service_query);

if (buscaServico.status === 'catalogo_vazio' || !AGENDAVEIS.length) {
  return saida('humano', { motivo: 'catalogo_vazio', handoff_motivo: 'configuracao_incompleta', resposta: resposta('humano', {}) });
}
if (buscaServico.status === 'ambiguo') {
  return saida('responder', { motivo: 'servico_ambiguo', resposta: resposta('qual_servico', { opcoes: buscaServico.opcoes.map((s) => s.nome) }) });
}
if (buscaServico.status === 'nao_encontrado') {
  return saida('responder', { motivo: 'servico_nao_confirmado', resposta: resposta('servico_nao_confirmado', { pedido: ent.service_query, servicos: nomesAgendaveis() }) });
}
if (buscaServico.status === 'ausente' && !escolhido) {
  return saida('responder', { motivo: 'servico_ausente', resposta: resposta('qual_servico', { opcoes: nomesAgendaveis() }) });
}

const servico = escolhido && escolhido.servico_id
  ? { id: escolhido.servico_id, nome: escolhido.servico_nome, duracao_minutos: escolhido.duracao_minutos }
  : buscaServico.servico;

if (!servico || !servico.id) {
  return saida('humano', { motivo: 'servico_sem_id', handoff_motivo: 'configuracao_incompleta', resposta: resposta('humano', {}) });
}
// Sem profissional ativo o servico nunca teria vaga: dizer "sem horario" seria
// enganoso, porque nao existe data em que ele apareceria.
if (servico.agendavel === false) {
  return saida('humano', { motivo: 'servico_sem_profissional', handoff_motivo: 'configuracao_incompleta', resposta: resposta('humano', {}) });
}

let profissional = null;
if (ent.professional_query) {
  const achado = acharProfissional(ent.professional_query);
  if (achado.status === 'ok') profissional = achado.profissional;
  else if (achado.status === 'ambiguo') {
    return saida('responder', { motivo: 'profissional_ambiguo', resposta: resposta('qual_profissional', { opcoes: achado.opcoes.map((p) => p.nome) }) });
  } else if (achado.status === 'nao_encontrado') {
    return saida('responder', { motivo: 'profissional_nao_confirmado', resposta: resposta('profissional_nao_confirmado', { profissionais: ctx.profissionais.map((p) => p.nome) }) });
  }
}
if (!profissional && ctx.empresa.exige_profissional) {
  return saida('responder', { motivo: 'profissional_obrigatorio', resposta: resposta('qual_profissional', { opcoes: ctx.profissionais.map((p) => p.nome) }) });
}

if (escolhido) {
  return irBuscarHorarios(
    montarBusca(partesLocais(escolhido.inicio), null, servico.id, escolhido.profissional_id),
    {
      motivo: 'selecao_de_horario_oferecido',
      servico,
      profissional: profissional || (escolhido.profissional_id ? { id: escolhido.profissional_id, nome: escolhido.profissional_nome } : null),
      horario_desejado: escolhido.inicio,
      reagendar_consulta_id: ctx.estado.reagendar_consulta_id,
    },
  );
}

const data = resolverData([ent.date_text || '', ctx.conteudo].join(' '));
if (data.tipo === 'dia' && data.ambiguo) {
  return saida('responder', {
    motivo: 'data_ambigua',
    resposta: resposta('data_ambigua', { nome_dia: data.nome_dia, hoje: isoLocal(agora, 12, 0), proxima: isoLocal(somarDias(agora, 7), 12, 0) }),
  });
}

const hora = resolverHora([ent.time_text || '', ent.date_text || '', ctx.conteudo]);
let horarioDesejado = null;
if (data.tipo === 'dia') {
  const inicioDia = isoLocal(data.p, hora ? hora.hora : DIA_FIM, hora ? hora.min : 0);
  if (new Date(inicioDia).getTime() <= new Date(ctx.agora_iso).getTime()) {
    return saida('responder', {
      motivo: 'data_no_passado',
      resposta: resposta('data_passada', { pedido: ent.date_text || ent.time_text || '', sugestao: isoLocal(somarDias(agora, 1), 9, 0) }),
    });
  }
  if (hora) horarioDesejado = isoLocal(data.p, hora.hora, hora.min);
}

let busca;
if (data.tipo === 'dia') {
  busca = montarBusca(data.p, ent.period, servico.id, profissional ? profissional.id : null);
} else {
  const inicioJanela = data.tipo === 'janela' ? data.p : agora;
  const dias = data.tipo === 'janela' ? (data.dias || 6) : JANELA_PADRAO_DIAS;
  const ini = montarBusca(inicioJanela, ent.period, servico.id, profissional ? profissional.id : null);
  busca = Object.assign(ini, { fim: isoLocal(somarDias(inicioJanela, dias), DIA_FIM, 0) });
}

return irBuscarHorarios(busca, {
  motivo: 'buscar_horarios',
  servico,
  profissional,
  periodo: ent.period,
  horario_desejado: horarioDesejado,
  reagendar_consulta_id: ctx.estado.reagendar_consulta_id,
});

// Le o envelope de /api/ai/disponibilidade e decide a resposta. Zero, um ou
// varios horarios sao casos distintos; nenhum horario e inventado nem vem do
// historico. Lista vazia com ok: true e resposta legitima, nao falha.
const MAX_OFERTAS = 2;
const PENDENTE_MINUTOS = 10;
const OFFSET_MIN = -180;
const CHAVE_MAX = 120; // limite de chave_idempotencia aceito pela API

const decisao = $('resolver e decidir').first().json;
const ctx = decisao.contexto;
const envelope = $input.first().json || {};

function numero(v) { const n = Number(v); return Number.isFinite(n) ? n : null; }
function turno(iso) {
  const h = new Date(new Date(iso).getTime() + OFFSET_MIN * 60000).getUTCHours();
  if (h < 12) return 'manha';
  if (h < 18) return 'tarde';
  return 'noite';
}
function dia(iso) { return new Date(new Date(iso).getTime() + OFFSET_MIN * 60000).toISOString().slice(0, 10); }

// Sem envelope (falha de rede, corpo sem `ok`) o resultado e desconhecido, e
// desconhecido nunca vira "nao tem horario".
const temEnvelope = typeof envelope.ok === 'boolean';
const dados = (temEnvelope && envelope.ok === true && envelope.data) ? envelope.data : {};
const falhou = !temEnvelope || envelope.ok !== true;
const codigoErro = temEnvelope && envelope.error ? String(envelope.error.code || '') : 'sem_envelope';

const agoraMs = new Date(ctx.agora_iso).getTime();
const procedimento = dados.procedimento || {};

// Os horarios ja vem no fuso do negocio e todo slot traz id_profissional: a
// API descarta slot sem profissional antes de responder.
const slots = (Array.isArray(dados.slots) ? dados.slots : [])
  .map((s) => ({
    inicio: s.inicio,
    fim: s.fim || null,
    profissional_id: numero(s.id_profissional),
    profissional_nome: String(s.profissional_nome || ''),
    servico_id: numero(procedimento.id) || (decisao.servico ? decisao.servico.id : null),
    servico_nome: String(procedimento.nome || (decisao.servico ? decisao.servico.nome : '')),
    duracao_minutos: numero(procedimento.duracao_minutos) || (decisao.servico ? decisao.servico.duracao_minutos : 60),
  }))
  .filter((s) => s.inicio && s.profissional_id && !Number.isNaN(new Date(s.inicio).getTime()))
  .filter((s) => new Date(s.inicio).getTime() > agoraMs)
  .sort((a, b) => new Date(a.inicio) - new Date(b.inicio));

function escolherDois(lista) {
  if (lista.length <= 1) return lista.slice(0, 1);
  const primeiro = lista[0];
  const diferente = lista.find((s) => turno(s.inicio) !== turno(primeiro.inicio) || dia(s.inicio) !== dia(primeiro.inicio));
  return diferente ? [primeiro, diferente] : lista.slice(0, MAX_OFERTAS);
}

function novaPendencia(slot) {
  const expira = new Date(agoraMs + PENDENTE_MINUTOS * 60000).toISOString();
  const base = {
    // acao_id vira a chave_idempotencia da criacao: repetir a mesma acao
    // devolve o mesmo agendamento em vez de criar um segundo.
    acao_id: `${ctx.msg_id}:${slot.inicio}`.slice(0, CHAVE_MAX),
    inicio: slot.inicio,
    duracao_minutos: slot.duracao_minutos,
    servico_id: slot.servico_id,
    servico_nome: slot.servico_nome,
    profissional_id: slot.profissional_id,
    profissional_nome: slot.profissional_nome,
    criada_em: ctx.agora_iso,
    expira_em: expira,
  };
  if (decisao.reagendar_consulta_id) {
    return Object.assign(base, { tipo: 'reagendar', consulta_id: decisao.reagendar_consulta_id });
  }
  return Object.assign(base, { tipo: 'agendar' });
}

function resultado(tipo, dadosResposta, pendente, oferecidos) {
  return [{
    json: {
      tipo_resposta: tipo,
      dados: dadosResposta || {},
      pendente_novo: pendente || null,
      estado_novo: {
        slots_oferecidos: oferecidos || [],
        consultas_candidatas: [],
        reagendar_consulta_id: pendente ? null : (decisao.reagendar_consulta_id || null),
      },
      log: Object.assign({}, decisao.log, {
        tipo_resposta: tipo,
        slots_encontrados: slots.length,
        total: numero(dados.total),
        truncado: dados.truncado === true,
        erro_ferramenta: falhou ? codigoErro : null,
      }),
    },
  }];
}

if (falhou) {
  return resultado('falha_temporaria', { operacao: 'consulta_de_horarios' }, null, ctx.estado.slots_oferecidos);
}

// truncado: a API cortou a lista no limite pedido, entao existem mais opcoes
// alem das duas ofertadas.
const maisOpcoes = dados.truncado === true;

if (decisao.horario_desejado) {
  const alvoMs = new Date(decisao.horario_desejado).getTime();
  const exato = slots.find((s) => new Date(s.inicio).getTime() === alvoMs);
  if (exato) {
    return resultado('pedir_confirmacao', { slot: exato, reagendamento: Boolean(decisao.reagendar_consulta_id) }, novaPendencia(exato), [exato]);
  }
  const alternativas = escolherDois(slots);
  if (!alternativas.length) {
    return resultado('sem_horarios', { servico: decisao.servico, ate: decisao.busca.fim }, null, []);
  }
  return resultado('horario_indisponivel', { pedido: decisao.horario_desejado, slots: alternativas }, null, alternativas);
}

if (!slots.length) {
  return resultado('sem_horarios', { servico: decisao.servico, ate: decisao.busca.fim }, null, []);
}

const ofertas = escolherDois(slots);
if (ofertas.length === 1) {
  return resultado('pedir_confirmacao', { slot: ofertas[0], unico: true, reagendamento: Boolean(decisao.reagendar_consulta_id) }, novaPendencia(ofertas[0]), ofertas);
}
return resultado(
  'dois_horarios',
  { slots: ofertas, servico: decisao.servico, mais_opcoes: maisOpcoes || slots.length > ofertas.length },
  null,
  ofertas,
);

// Le o envelope da API depois da escrita. So existe sucesso com ok: true E
// data.agendamento.id; qualquer outra coisa tem rota fixa e nenhuma delas
// anuncia sucesso ao cliente. `repetida: true` tambem e sucesso: a API
// devolveu o mesmo agendamento em vez de criar um segundo.
const OFFSET_MIN = -180;
const DIAS = ['domingo', 'segunda-feira', 'terça-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira', 'sábado'];

// O horario saiu da agenda entre a oferta e o "sim": reoferta, sem pessoa.
const REOFERTAR_HORARIO = ['HORARIO_INDISPONIVEL', 'CONFLITO_HORARIO'];
// O catalogo mudou: reoferta o que existe hoje, sem pessoa.
const REOFERTAR_CATALOGO = ['PROCEDIMENTO_INVALIDO', 'PROFISSIONAL_INVALIDO'];
// A consulta nao e mais reagendavel ou nao e deste cliente: lista de novo.
const LISTAR_DE_NOVO = ['CONSULTA_NAO_ENCONTRADA', 'CONSULTA_NAO_REAGENDAVEL'];

const decisao = $('resolver e decidir').first().json;
const ctx = decisao.contexto;
const pendente = decisao.pendente || {};
const envelope = $input.first().json || {};

function pad(n) { return String(n).padStart(2, '0'); }
function quando(iso) {
  const d = new Date(new Date(iso).getTime() + OFFSET_MIN * 60000);
  const m = d.getUTCMinutes();
  const hora = m ? `${d.getUTCHours()}h${pad(m)}` : `${d.getUTCHours()}h`;
  return `${DIAS[d.getUTCDay()]} (${pad(d.getUTCDate())}/${pad(d.getUTCMonth() + 1)}) às ${hora}`;
}

const temEnvelope = typeof envelope.ok === 'boolean';
const dados = envelope.data || {};
const agendamento = dados.agendamento || null;
const id = agendamento && Number.isFinite(Number(agendamento.id)) ? Number(agendamento.id) : null;
const codigo = temEnvelope && envelope.error ? String(envelope.error.code || '') : '';

// O horario anunciado e o que a API confirmou ter gravado, nao o que pedimos.
const inicioConfirmado = (agendamento && agendamento.inicio) || pendente.inicio || null;
const nomeServico = (agendamento && agendamento.procedimento && agendamento.procedimento.nome)
  || pendente.servico_nome || 'seu atendimento';
const nomeProfissional = (agendamento && agendamento.profissional && agendamento.profissional.nome)
  || pendente.profissional_nome || '';
const prof = nomeProfissional ? ` com ${nomeProfissional}` : '';
const resumo = inicioConfirmado ? `${nomeServico}, ${quando(inicioConfirmado)}${prof}` : 'seu atendimento';

const nomesAgendaveis = (ctx.servicos || []).filter((s) => s.agendavel !== false).map((s) => s.nome);
const nomesProfissionais = (ctx.profissionais || []).map((p) => p.nome);

let tipo;
let sucesso = false;
let precisaHumano = true;
let dadosResposta = {};

if (!temEnvelope) {
  // Sem envelope o resultado e desconhecido: nada pode ser afirmado.
  tipo = 'falha_ferramenta';
  dadosResposta = { operacao: pendente.tipo || null };
} else if (envelope.ok === true && id) {
  sucesso = true;
  precisaHumano = false;
  tipo = pendente.tipo === 'cancelar' ? 'cancelado' : (pendente.tipo === 'reagendar' ? 'reagendado' : 'agendado');
  dadosResposta = { resumo, consulta_id: id };
} else if (envelope.ok === true) {
  tipo = 'resultado_sem_id';
} else if (REOFERTAR_HORARIO.includes(codigo)) {
  precisaHumano = false;
  tipo = 'horario_ocupado';
} else if (codigo === 'PROFISSIONAL_INVALIDO') {
  precisaHumano = false;
  tipo = 'profissional_nao_confirmado';
  dadosResposta = { profissionais: nomesProfissionais };
} else if (REOFERTAR_CATALOGO.includes(codigo)) {
  precisaHumano = false;
  tipo = 'servico_nao_confirmado';
  dadosResposta = { servicos: nomesAgendaveis };
} else if (LISTAR_DE_NOVO.includes(codigo)) {
  precisaHumano = false;
  tipo = 'consulta_nao_encontrada';
} else {
  // Fecha por padrao: autenticacao, instancia, empresa, entrada invalida,
  // chave conflitante, agendamento inativo, falha temporaria persistente e
  // qualquer codigo novo param aqui e chamam uma pessoa.
  tipo = 'falha_ferramenta';
  dadosResposta = { operacao: pendente.tipo || null };
}

return [{
  json: {
    sucesso,
    precisa_humano: precisaHumano,
    tipo_resposta: tipo,
    dados: dadosResposta,
    pendente_novo: null,
    estado_novo: { slots_oferecidos: [], consultas_candidatas: [], reagendar_consulta_id: null },
    log: Object.assign({}, decisao.log, {
      operacao: pendente.tipo || null,
      resultado: tipo,
      consulta_id: id,
      repetida: agendamento ? dados.repetida === true : null,
      codigo_erro: codigo || (temEnvelope ? null : 'sem_envelope'),
    }),
  },
}];

// Trata os agendamentos do proprio cliente. O filtro de empresa e de cliente e
// do servidor: a rota deriva a empresa da instancia e o cliente do telefone.
// Decide listar, pedir escolha, abrir cancelamento ou reagendamento.
const PENDENTE_MINUTOS = 10;
const OFFSET_MIN = -180;
const CHAVE_MAX = 120;
// Vocabulario da API: `cancelado` e `concluido` nao entram na lista de vivos.
const STATUS_ATIVOS = ['pendente', 'agendado', 'confirmado'];

const decisao = $('resolver e decidir').first().json;
const ctx = decisao.contexto;
const envelope = $input.first().json || {};

function numero(v) { const n = Number(v); return Number.isFinite(n) ? n : null; }
function normalizar(s) {
  return String(s === null || s === undefined ? '' : s).toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s/]/g, ' ').replace(/\s+/g, ' ').trim();
}

const temEnvelope = typeof envelope.ok === 'boolean';
const dados = (temEnvelope && envelope.ok === true && envelope.data) ? envelope.data : {};
const falhou = !temEnvelope || envelope.ok !== true;
const codigoErro = temEnvelope && envelope.error ? String(envelope.error.code || '') : 'sem_envelope';

const agoraMs = new Date(ctx.agora_iso).getTime();
const DIAS = ['domingo', 'segunda', 'terca', 'quarta', 'quinta', 'sexta', 'sabado'];

const consultas = (Array.isArray(dados.agendamentos) ? dados.agendamentos : [])
  .map((a) => {
    const procedimento = a.procedimento || {};
    const profissional = a.profissional || {};
    return {
      consulta_id: numero(a.id),
      inicio: a.inicio,
      status: String(a.status || ''),
      servico_id: numero(procedimento.id),
      servico_nome: String(procedimento.nome || 'seu atendimento'),
      duracao_minutos: numero(procedimento.duracao_minutos) || 60,
      profissional_id: numero(profissional.id),
      profissional_nome: String(profissional.nome || ''),
    };
  })
  .filter((c) => c.consulta_id && c.inicio && !Number.isNaN(new Date(c.inicio).getTime()))
  .filter((c) => new Date(c.inicio).getTime() > agoraMs)
  .filter((c) => !c.status || STATUS_ATIVOS.includes(c.status.toLowerCase()))
  .sort((a, b) => new Date(a.inicio) - new Date(b.inicio));

function pista(consulta) {
  const texto = normalizar(`${decisao.interp.entities.appointment_hint || ''} ${decisao.interp.entities.date_text || ''} ${ctx.conteudo}`);
  if (!texto) return false;
  const local = new Date(new Date(consulta.inicio).getTime() + OFFSET_MIN * 60000);
  const nomeDia = DIAS[local.getUTCDay()];
  const diaMes = String(local.getUTCDate());
  const hora = String(local.getUTCHours());
  return texto.includes(nomeDia)
    || new RegExp(`\\b${diaMes}\\b`).test(texto)
    || new RegExp(`\\b${hora}\\s?h`).test(texto)
    || (consulta.servico_nome && texto.includes(normalizar(consulta.servico_nome)));
}

function resultado(tipo, dadosResposta, pendente, estado) {
  return [{
    json: {
      tipo_resposta: tipo,
      dados: dadosResposta || {},
      pendente_novo: pendente || null,
      estado_novo: Object.assign({ slots_oferecidos: [], consultas_candidatas: [], reagendar_consulta_id: null }, estado || {}),
      log: Object.assign({}, decisao.log, {
        tipo_resposta: tipo,
        consultas_encontradas: consultas.length,
        erro_ferramenta: falhou ? codigoErro : null,
      }),
    },
  }];
}

function novaPendenciaCancelar(consulta) {
  return {
    tipo: 'cancelar',
    acao_id: `${ctx.msg_id}:cancelar:${consulta.consulta_id}`.slice(0, CHAVE_MAX),
    consulta_id: consulta.consulta_id,
    inicio: consulta.inicio,
    servico_nome: consulta.servico_nome,
    profissional_nome: consulta.profissional_nome,
    criada_em: ctx.agora_iso,
    expira_em: new Date(agoraMs + PENDENTE_MINUTOS * 60000).toISOString(),
  };
}

// Consulta que falhou nao e agenda vazia: dizer "voce nao tem horario" seria
// afirmar algo que a ferramenta nao respondeu.
if (falhou) {
  return resultado('falha_temporaria', { operacao: 'consulta_de_agendamentos' }, null, {});
}

if (!consultas.length) {
  return resultado('sem_consultas', { objetivo: decisao.objetivo }, null, {});
}

if (decisao.objetivo === 'listar') {
  return resultado('lista_consultas', { consultas: consultas.slice(0, 3) }, null, { consultas_candidatas: consultas.slice(0, 3) });
}

const candidatas = consultas.length === 1 ? consultas : consultas.filter(pista);
if (candidatas.length !== 1) {
  return resultado('escolher_consulta', { consultas: consultas.slice(0, 3), objetivo: decisao.objetivo }, null, { consultas_candidatas: consultas.slice(0, 3) });
}

const escolhida = candidatas[0];
if (decisao.objetivo === 'cancelar') {
  return resultado('pedir_confirmacao_cancelamento', { consulta: escolhida }, novaPendenciaCancelar(escolhida), {});
}
return resultado('pedir_nova_data', { consulta: escolhida }, null, { reagendar_consulta_id: escolhida.consulta_id });

// Confirma a atualizacao cadastral so quando a API devolveu ok com os campos
// que ela realmente gravou. `campos_atualizados` vem do servidor, nao do pedido.
const ROTULOS = { nome: 'nome', email: 'e-mail', data_nascimento: 'data de nascimento', interesses: 'preferências' };

const decisao = $('resolver e decidir').first().json;
const envelope = $input.first().json || {};

const temEnvelope = typeof envelope.ok === 'boolean';
const dados = (temEnvelope && envelope.ok === true && envelope.data) ? envelope.data : {};
const ok = Boolean(dados.cliente);
const codigoErro = temEnvelope && envelope.error ? String(envelope.error.code || '') : 'sem_envelope';

const gravados = Array.isArray(dados.campos_atualizados) ? dados.campos_atualizados : [];
const campos = gravados.map((c) => ROTULOS[c] || c);

return [{
  json: {
    tipo_resposta: ok ? 'cadastro_atualizado' : 'falha_temporaria',
    dados: ok ? { campos } : { operacao: 'atualizacao_de_cadastro' },
    pendente_novo: null,
    estado_novo: { slots_oferecidos: [], consultas_candidatas: [], reagendar_consulta_id: null },
    log: Object.assign({}, decisao.log, {
      resultado: ok ? 'cadastro_atualizado' : 'falha',
      campos,
      erro_ferramenta: ok ? null : codigoErro,
    }),
  },
}];

// Mensagens operacionais deterministicas. Nenhuma IA e chamada para dizer que um
// horario foi marcado, alterado ou cancelado.
const OFFSET_MIN = -180;
const HISTORICO_MAX = 6;
const DIAS = ['domingo', 'segunda-feira', 'terça-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira', 'sábado'];
// Vocabulario que so o sistema pode usar, e so depois de um efeito verificado.
const AFIRMA_EFEITO = /agendad|confirmad|cancelad|remarcad|reservad|marcad/i;

const decisao = $('resolver e decidir').first().json;
const ctx = decisao.contexto;
const item = $input.first().json;

const tipo = item.tipo_resposta || (item.resposta && item.resposta.tipo) || 'livre';
const dados = item.dados || (item.resposta && item.resposta.dados) || {};
const pendenteNovo = item.pendente_novo || null;
const estadoNovo = item.estado_novo || {};

function local(iso) { return new Date(new Date(iso).getTime() + OFFSET_MIN * 60000); }
function pad(n) { return String(n).padStart(2, '0'); }
function hora(iso) {
  const d = local(iso);
  const m = d.getUTCMinutes();
  return m ? `${d.getUTCHours()}h${pad(m)}` : `${d.getUTCHours()}h`;
}
function data(iso) {
  const d = local(iso);
  return `${pad(d.getUTCDate())}/${pad(d.getUTCMonth() + 1)}`;
}
function quando(iso) {
  const d = local(iso);
  return `${DIAS[d.getUTCDay()]} (${data(iso)}) às ${hora(iso)}`;
}
function lista(itens) { return itens.map((t) => `- ${t}`).join('\n'); }

const empresa = ctx.empresa.nome;
const nome = ctx.cliente.primeiro_nome;
const ola = nome ? `${nome}, ` : '';
// Nenhum no deste fluxo avisa o negocio. O que acontece de verdade e a IA
// parar; a conversa segue no WhatsApp do proprio negocio. O texto diz isso.
const deixarComEquipe = `Vou parar por aqui e deixar com a equipe do ${empresa}, que continua com você nesta conversa.`;

function descreverSlot(s) {
  const prof = s.profissional_nome ? ` com ${s.profissional_nome}` : '';
  return `${quando(s.inicio)}${prof}`;
}
function descreverConsulta(c) {
  const prof = c.profissional_nome ? ` com ${c.profissional_nome}` : '';
  return `${c.servico_nome} - ${quando(c.inicio)}${prof}`;
}

const TEXTOS = {
  livre: () => String(dados.reply || '').trim() || 'Não consegui confirmar essa informação por aqui. Quer falar com alguém da equipe?',
  esclarecer: () => String(dados.reply || '').trim() || 'Não entendi direito. Pode me dizer de outro jeito?',
  humano: () => deixarComEquipe,
  sem_pendente: () => 'Não tenho nada pendente aqui para confirmar. Quer que eu veja horários?',
  pendente_expirada: () => 'Esse horário já expirou aqui. Quer que eu procure de novo?',
  pendente_descartada: () => 'Ok, deixei como está. Se mudar de ideia é só falar.',
  qual_servico: () => {
    const opcoes = (dados.opcoes || []).slice(0, 6);
    return opcoes.length
      ? `Qual desses você quer?\n${lista(opcoes)}`
      : 'Qual serviço você quer?';
  },
  servico_nao_confirmado: () => {
    const opcoes = (dados.servicos || []).slice(0, 6);
    const inicio = 'Não consegui confirmar esse serviço na nossa lista.';
    return opcoes.length ? `${inicio}\nO que temos é:\n${lista(opcoes)}\nAlgum desses?` : `${inicio} Quer falar com a equipe do ${empresa}?`;
  },
  qual_profissional: () => {
    const opcoes = (dados.opcoes || []).slice(0, 6);
    return opcoes.length ? `Com qual profissional?\n${lista(opcoes)}` : 'Com qual profissional você prefere?';
  },
  profissional_nao_confirmado: () => {
    const opcoes = (dados.profissionais || []).slice(0, 6);
    return opcoes.length ? `Não consegui confirmar esse nome.\nQuem atende é:\n${lista(opcoes)}` : 'Não consegui confirmar esse nome por aqui.';
  },
  data_ambigua: () => `Só para eu não errar: ${data(dados.hoje)} (hoje) ou ${data(dados.proxima)}?`,
  data_passada: () => `Essa data já passou. Quer que eu procure a partir de ${data(dados.sugestao)}?`,
  sem_horarios: () => {
    const servico = dados.servico ? ` para ${dados.servico.nome}` : '';
    return `Não achei horário livre${servico} até ${data(dados.ate)}.\nQuer que eu procure em outra data?`;
  },
  dois_horarios: () => {
    const servico = dados.servico ? ` para ${dados.servico.nome}` : '';
    const opcoes = (dados.slots || []).map((s, i) => `${i + 1}) ${descreverSlot(s)}`).join('\n');
    const extra = dados.mais_opcoes ? '\nSe nenhum servir, tenho outras opções.' : '';
    return `Tenho estes horários${servico}:\n${opcoes}\nQual prefere?${extra}`;
  },
  horario_indisponivel: () => {
    const opcoes = (dados.slots || []).map((s, i) => `${i + 1}) ${descreverSlot(s)}`).join('\n');
    return `Esse horário não está livre.\nTenho:\n${opcoes}\nAlgum serve?`;
  },
  horario_ocupado: () => 'Esse horário acabou de ser ocupado. Nada foi alterado na sua agenda.\nQuer que eu procure outro?',
  qual_horario: () => {
    const opcoes = (dados.slots || []).map((s, i) => `${i + 1}) ${descreverSlot(s)}`).join('\n');
    return `Qual dos dois você quer?\n${opcoes}`;
  },
  pedir_confirmacao: () => {
    const s = dados.slot;
    const acao = dados.reagendamento ? 'Remarco' : 'Confirmo';
    return `${acao} então: ${s.servico_nome}, ${descreverSlot(s)}.\nPosso ${dados.reagendamento ? 'remarcar' : 'marcar'}?`;
  },
  pedir_confirmacao_cancelamento: () => `Você tem ${descreverConsulta(dados.consulta)}.\nConfirma o cancelamento?`,
  pedir_nova_data: () => `Seu horário atual é ${descreverConsulta(dados.consulta)}.\nPara quando você quer remarcar?`,
  lista_consultas: () => {
    const itens = (dados.consultas || []).map((c) => descreverConsulta(c));
    return itens.length === 1
      ? `Seu horário é ${itens[0]}.`
      : `Seus horários marcados:\n${lista(itens)}`;
  },
  sem_consultas: () => 'Não encontrei nenhum horário marcado no seu nome. Quer marcar um?',
  consulta_nao_encontrada: () => 'Não encontrei esse horário na sua agenda agora. Nada foi alterado.\nQuer que eu liste os seus horários marcados?',
  escolher_consulta: () => {
    const itens = (dados.consultas || []).map((c, i) => `${i + 1}) ${descreverConsulta(c)}`).join('\n');
    return `Você tem mais de um horário marcado:\n${itens}\nQual deles?`;
  },
  agendado: () => `Pronto, ${ola}está marcado: ${dados.resumo}.\nSe precisar mudar, é só me chamar.`,
  reagendado: () => `Remarcado. Agora ficou ${dados.resumo}.\nO horário anterior foi liberado.`,
  cancelado: () => `Cancelei ${dados.resumo}.\nQuando quiser remarcar, é só falar.`,
  // Leitura que nao respondeu: nada foi alterado e a IA continua na conversa.
  falha_temporaria: () => 'Não consegui concluir isso agora. Nada foi alterado.\nQuer tentar de novo em instantes?',
  // Escrita sem resultado confiavel: a IA para e a equipe assume a conversa.
  falha_ferramenta: () => `Não consegui concluir agora por um problema no sistema. Nada foi alterado na sua agenda.\n${deixarComEquipe}`,
  resultado_sem_id: () => `Não recebi a confirmação do sistema, então não vou afirmar nada. Nada foi alterado na sua agenda.\n${deixarComEquipe}`,
  cadastro_atualizado: () => `Anotei aqui. ${dados.campos && dados.campos.length ? `Atualizei: ${dados.campos.join(', ')}.` : ''}`.trim(),
};

let texto = (TEXTOS[tipo] || TEXTOS.livre)();

// Verificador deterministico de sucesso: texto escrito pela IA nunca afirma
// que algo foi marcado, remarcado ou cancelado. Quem pode dizer isso e o
// modelo fixo acima, e so depois de um efeito verificado nesta execucao.
if (['livre', 'esclarecer'].includes(tipo) && item.sucesso !== true && AFIRMA_EFEITO.test(texto)) {
  texto = 'Sobre isso eu não consigo dar uma resposta por aqui. Quer que eu veja os horários disponíveis?';
}

// Primeira mensagem da conversa: identifica a empresa uma unica vez.
const primeiraMensagem = !(ctx.estado.historico || []).length;
if (primeiraMensagem && tipo !== 'livre' && tipo !== 'esclarecer') {
  texto = `Aqui é o atendimento do ${empresa}.\n${texto}`;
}

// Audio com transcricao incerta: devolve o entendimento antes de qualquer acao.
if (ctx.entrada_incerta && ['pedir_confirmacao', 'pedir_confirmacao_cancelamento'].includes(tipo)) {
  texto = `Não peguei tudo do áudio, então confirmo com você:\n${texto}`;
}

// Cliente mudou de assunto com uma acao pendente aberta: responde e retoma.
const pendenteAtual = ctx.pendente;
if (!pendenteNovo && pendenteAtual && pendenteAtual.inicio && ['livre', 'esclarecer'].includes(tipo)) {
  const acao = pendenteAtual.tipo === 'cancelar' ? 'Confirma o cancelamento de' : 'Confirmo o horário de';
  texto = `${texto}\n${acao} ${quando(pendenteAtual.inicio)}?`;
}

const historico = (ctx.estado.historico || [])
  .concat([{ r: 'cliente', t: String(ctx.conteudo).slice(0, 240) }, { r: 'assistente', t: texto.slice(0, 240) }])
  .slice(-HISTORICO_MAX);

return [{
  json: {
    texto,
    tipo_resposta: tipo,
    pendente_novo: pendenteNovo,
    tem_pendente_novo: Boolean(pendenteNovo && pendenteNovo.tipo),
    estado: {
      historico,
      slots_oferecidos: estadoNovo.slots_oferecidos || [],
      consultas_candidatas: estadoNovo.consultas_candidatas || [],
      reagendar_consulta_id: estadoNovo.reagendar_consulta_id || null,
      atualizado_em: ctx.agora_iso,
    },
    log: Object.assign({ tipo_resposta: tipo }, item.log || decisao.log || {}),
  },
}];

// Quebra a resposta em no maximo 3 mensagens curtas de WhatsApp.
const MAX_PARTES = 3;
const MAX_CARACTERES = 900;

const item = $input.first().json;
const partes = String(item.texto || '')
  .split(/\n{2,}/)
  .map((p) => p.trim())
  .filter(Boolean)
  .slice(0, MAX_PARTES)
  .map((p) => p.slice(0, MAX_CARACTERES));

return [{ json: { partes: partes.length ? partes : ['Não consegui montar a resposta agora. Vou deixar com a equipe, que continua com você nesta conversa.'] } }];

// Registro da decisao para auditoria. Sem telefone, sem nome e sem texto da
// conversa. A instancia identifica o tenant; ids internos de empresa e de
// cliente nao existem mais no fluxo, porque a API nao os devolve.
const decisao = $('resolver e decidir').first().json;
const resposta = $('montar resposta').first().json;

return [{
  json: {
    registro: 'atendimento_v2',
    msg_id: decisao.contexto.msg_id,
    instance: decisao.contexto.instance,
    intent: decisao.interp ? decisao.interp.intent : null,
    confidence: decisao.interp ? decisao.interp.confidence : null,
    rota: decisao.rota,
    motivo: decisao.motivo,
    tipo_resposta: resposta.tipo_resposta,
    acao_pendente: resposta.tem_pendente_novo ? resposta.pendente_novo.tipo : null,
    detalhe: resposta.log || {},
    em: decisao.contexto.agora_iso,
  },
}];
